"""Measure a possible derived-array bundle without saving any corpus arrays."""
import replay as r
import zlib
C=r.verify();manifest={x['name']:x for x in r.read('inputs-frozen.json')['corpus']}
assert all(r.ah(a)==manifest[name]['lengths_sha256'] for name,a in C.items())
eligible={n:a for n,a in C.items() if len(a)>=2928}
obj=dict(implemented=False,executed_normalization_unchanged=True,arrays_equal_pinned_normalization=94,encoding='little-endian signed16-bit integer per normalized word',all94_raw_bytes=sum(a.nbytes for a in C.values()),eligible84_raw_bytes=sum(a.nbytes for a in eligible.values()),all94_individually_deflated_bytes=sum(len(zlib.compress(a.astype('<i2').tobytes(),9)) for a in C.values()),eligible84_individually_deflated_bytes=sum(len(zlib.compress(a.astype('<i2').tobytes(),9)) for a in eligible.values()),contents_saved=False,recommendation='A future bundle can store all94 arrays plus exact keys/order, lengths and per-array hashes, source raw hashes and manuscript inputs. The10short arrays add little and preserve unchanged source corpus totals and selection metadata. The original scanner consumes these exact int16 arrays; only the corpus loader would need an explicitly declared adapter.',equivalence='Every array hash was recomputed from the unchanged source normalization and agrees with the pre-target manifest. A loader adapter must validate the entire name/order/hash set, then return identical arrays and metadata; independent full array equality and same-source small fixture output parity should precede any new bundle claim.',limits='This assessment only computes sizes in memory. No derived arrays or corpus bytes are saved, distributed, or used for a new scan. Word-length arrays omit word spellings, but no legal conclusion about redistribution is asserted. An array bundle reuses recorded normalization; it does not independently rerun normalization or authenticate historical224-text bytes.')
r.write('derived-array-assessment.json',obj)
print('Array assessment:',obj['all94_raw_bytes'],'raw bytes;',obj['all94_individually_deflated_bytes'],'deflated bytes; none saved.')
